<span class="line"><span style="color:#E06C75;">      when</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">ansible_distribution == &quot;Ubuntu&quot; and ansible_distribution_major_version == &quot;20&quot;</span></span>
